package com.rouddy.smstransmitter

import java.security.KeyFactory
import java.security.PrivateKey
import java.security.Signature
import java.security.spec.PKCS8EncodedKeySpec
import java.util.Base64
import java.util.UUID

/**
 * Creates short-lived ES256 JWTs that the sms_transmitter_rocket server accepts.
 *
 * The private key is the shared key generated by `sms_transmitter_rocket/script/generate_keys.sh`
 * and embedded into BuildConfig at build time.
 */
class JwtSigner(
    private val privateKey: PrivateKey,
    private val lifetimeSeconds: Long = DEFAULT_LIFETIME_SECONDS,
    private val nowSeconds: () -> Long = { System.currentTimeMillis() / 1000 },
) {

    fun createToken(): String {
        val now = nowSeconds()
        val header = """{"alg":"ES256","typ":"JWT"}"""
        val payload = """{"iat":$now,"exp":${now + lifetimeSeconds},"jti":"${UUID.randomUUID()}"}"""
        val signingInput = "${base64Url(header.toByteArray())}.${base64Url(payload.toByteArray())}"

        val derSignature = Signature.getInstance("SHA256withECDSA").run {
            initSign(privateKey)
            update(signingInput.toByteArray())
            sign()
        }
        return "$signingInput.${base64Url(derToRawSignature(derSignature))}"
    }

    companion object {
        const val DEFAULT_LIFETIME_SECONDS = 300L
        private const val COORDINATE_SIZE = 32

        /** Builds a signer from a base64-encoded PKCS#8 EC private key (PEM body without headers). */
        fun fromPkcs8Base64(privateKeyBase64: String): JwtSigner {
            val keyBytes = Base64.getDecoder().decode(privateKeyBase64)
            val privateKey = KeyFactory.getInstance("EC").generatePrivate(PKCS8EncodedKeySpec(keyBytes))
            return JwtSigner(privateKey)
        }

        private fun base64Url(bytes: ByteArray): String =
            Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)

        /**
         * JCA returns ECDSA signatures as DER `SEQUENCE { INTEGER r, INTEGER s }`,
         * but JWS ES256 requires the raw 64-byte `r || s` form.
         */
        internal fun derToRawSignature(der: ByteArray): ByteArray {
            require(der.size > 2 && der[0] == 0x30.toByte()) { "Not a DER ECDSA signature" }
            var offset = if (der[1].toInt() and 0x80 != 0) 2 + (der[1].toInt() and 0x7f) else 2

            val raw = ByteArray(COORDINATE_SIZE * 2)
            for (index in 0 until 2) {
                require(der[offset] == 0x02.toByte()) { "Malformed DER ECDSA signature" }
                val length = der[offset + 1].toInt() and 0xff
                var start = offset + 2
                var size = length
                // Drop the sign-padding zero bytes DER adds to positive integers.
                while (size > COORDINATE_SIZE && der[start] == 0.toByte()) {
                    start++
                    size--
                }
                require(size <= COORDINATE_SIZE) { "ECDSA coordinate too long" }
                System.arraycopy(der, start, raw, (index + 1) * COORDINATE_SIZE - size, size)
                offset += 2 + length
            }
            return raw
        }
    }
}
